// Code generated by cmd/gen-notification-codes. DO NOT EDIT.
// Source: internal/notifications/codes.go
// Run `make generate-notification-codes` to refresh.
//
// Every notification identifier the server can emit. Route on these.
//
// A notification's `title` and `description` are text to show a person and
// may be reworded in any release. Never route on them, never use one as a
// map key, and never compare one: the browser used to pick which connection
// panel got a notification's detail by matching the title sentence, and one
// capitalised letter server-side would have blanked both panels with nothing
// failing anywhere.

export const NOTIFICATION_CODES = {
  gitConnectionBroken: "git_connection_broken",
  argocdRepoBroken: "argocd_repo_broken",
  argocdAuthFailed: "argocd_auth_failed",
  argocdUnreachable: "argocd_unreachable",
  argocdForbidden: "argocd_forbidden",
  addonUpgradeAvailable: "addon_upgrade_available",
  addonMajorUpdate: "addon_major_update",
  addonVersionDrift: "addon_version_drift",
} as const

// The set of identifiers the server declares. An identifier outside it is one
// this build does not know: show the notification with its own title and
// description rather than routing it, and never drop it silently.
export type NotificationCode = (typeof NOTIFICATION_CODES)[keyof typeof NOTIFICATION_CODES]

export type NotificationCodeName = keyof typeof NOTIFICATION_CODES
